INSERT INTO `pagini` VALUES (1,'finantare','credit-auto','Credit auto în rate','Credit auto în rate pentru mașini second hand, fără garanții materiale','Credit auto second hand în rate | Autoland România','Rate pentru mașini second hand de până la 15 ani: avans de la 0% în funcție de profil, venit minim 2.000 RON, fără garanții materiale. Cere oferta.','<div class=\"ap\">\r\n<p class=\"ap-lead\"><strong>Ratele sunt pentru oricine: persoane fizice și firme.</strong> Mașini de până la 15 ani, avans de la 0% în funcție de venituri și istoric. Mașina e a ta imediat, fără valoare reziduală, iar garanția este mașina în sine, fără girant.</p>\r\n<div class=\"ap-facts\"><div><span>Avans</span><strong>0–80%</strong></div><div><span>Durată</span><strong>1–5 ani</strong></div><div><span>Vechimea mașinii</span><strong>max. 15 ani</strong></div><div><span>Valoare minimă</span><strong>3.000 EUR</strong></div></div>\r\n<p class=\"ap-actions\"><a class=\"ap-btn\" href=\"https://autolandromania.ro/cerere_oferta.php\">Cere o ofertă în rate</a></p>\r\n<h2>Condiții pe scurt</h2>\r\n<p><strong>Valoarea minimă este 3.000 EUR, durata 1–5 ani, iar avansul poate varia între 0% și 80%.</strong></p>\r\n<div class=\"ap-table\"><table>\r\n<tr><th>Element</th><th>Valoare</th></tr>\r\n<tr><td>Valoare minimă a mașinii</td><td>3.000 EUR</td></tr>\r\n<tr><td>Vechimea mașinii</td><td>maximum 15 ani</td></tr>\r\n<tr><td>Durată</td><td>1–5 ani (12–60 de luni)</td></tr>\r\n<tr><td>Avans</td><td>0–80%, în funcție de venituri și istoricul bancar</td></tr>\r\n<tr><td>Dobândă</td><td>stabilită individual, până la 18,5% pe an (RON)</td></tr>\r\n<tr><td>Comision</td><td>2,5% din valoarea mașinii, o singură dată</td></tr>\r\n<tr><td>Valoare reziduală</td><td>0% (proprietate imediată)</td></tr>\r\n<tr><td>Garanții</td><td>fără garanții bancare sau materiale</td></tr>\r\n</table></div>\r\n<h2>Criterii de eligibilitate</h2>\r\n<p><strong>Persoană fizică: minimum 2.000 RON/lună și 3 luni vechime.</strong> Vârsta minimă este 18 ani. Sunt acceptate și venituri din străinătate și, cu avans mai mare, istoric bancar dificil.</p>\r\n<div class=\"ap-table\"><table>\r\n<tr><th></th><th>Venituri din România</th><th>Venituri din străinătate</th><th>Firme</th></tr>\r\n<tr><td>Vechime venit / activitate</td><td>minimum 3 luni</td><td>minimum 6 luni</td><td>activitate minimum 3 luni <mark>[de confirmat]</mark></td></tr>\r\n<tr><td>Venit minim</td><td>2.000 RON/lună, declarat</td><td>dovedit cu extrase de cont sau contract de muncă tradus</td><td>–</td></tr>\r\n<tr><td>Vârstă minimă</td><td>18 ani</td><td>20 de ani</td><td>–</td></tr>\r\n<tr><td>Avans</td><td>de la 0%</td><td>de la 20%</td><td>de la 0% la anumite profiluri</td></tr>\r\n</table></div>\r\n<h2>Ce poți face în timpul contractului</h2>\r\n<p><strong>Poți plăti rate în avans, poți închide contractul mai devreme sau poți vinde ori ceda mașina.</strong> După 6 luni poți achita integral mașina fără costuri suplimentare.</p>\r\n<ul>\r\n <li>Plata în avans se face cu o notificare scrisă; ratele rămase se recalculează automat și scad.</li>\r\n <li>Dobânda se calculează pentru perioada efectiv folosită, deci închiderea anticipată costă mai puțin decât ai planificat.</li>\r\n <li>Poți vinde mașina și achita restul contractului sau poți ceda contractul altei persoane, cu acordul finanțatorului.</li>\r\n</ul>\r\n<h2>Ce e inclus</h2>\r\n<p><strong>Ne ocupăm de înmatriculare; asigurarea RCA/CASCO, asistența rutieră și garanția pot fi incluse.</strong> Garanția este de la prima zi, între 1 și 3 ani, în funcție de mașină (<a href=\"https://autolandromania.ro/garantie.php\">detalii</a>).</p>\r\n<h2>Cum începi</h2>\r\n<ol class=\"ap-steps\">\r\n <li><strong>Pasul 1:</strong> Alegi mașina dintre ofertele noastre și ceri oferta.</li>\r\n <li><strong>Pasul 2:</strong> Trimiți actele din <a href=\"https://autolandromania.ro/finantare/acte-necesare/\">lista pentru persoane fizice</a>.</li>\r\n <li><strong>Pasul 3:</strong> După aprobare semnezi contractul și preiei mașina.</li>\r\n</ol>\r\n<div id=\"faq\" class=\"ap-faq\"><h2>Întrebări frecvente</h2><h3>Ce mașini pot cumpăra în rate?</h3><p>Autoturisme second hand de până la 15 ani, de la 3.000 EUR.</p><h3>Ce venit trebuie să am?</h3><p>Minimum 2.000 RON/lună, declarat oficial prin adeverință.</p><h3>Pot plăti mai multe rate în avans?</h3><p>Da, cu notificare scrisă. Ratele rămase se recalculează automat sau se reduce durata contractului.</p><h3>Pot să cesionez contractul?</h3><p>Da. Noua persoană depune documentele și trebuie aprobată de finanțator; preia ratele rămase.</p></div>\r\n<p class=\"ap-related\"><span>Vezi și:</span> <a href=\"https://autolandromania.ro/finantare/avans-minim/\">Avans minim</a> <a href=\"https://autolandromania.ro/finantare/calculator-rate/\">Calculator rată</a> <a href=\"https://autolandromania.ro/finantare/acte-necesare/\">Acte necesare</a></p>\r\n</div>','published',1,'2026-10-23 10:46:57'),(2,'finantare','leasing-financiar','Leasing financiar','Leasing financiar auto pentru firme: condiții, avantaje fiscale, acte','Leasing financiar auto pentru firme | Autoland România','Leasing financiar pentru firme, PFA și firme noi: TVA deductibil, avans 15–50%, 1–5 ani, aprobare în 2–3 zile. Vezi condițiile și actele.','<div class=\"ap\">\r\n<p class=\"ap-lead\"><strong>Recuperezi TVA-ul și devii proprietar la final.</strong> Se aprobă de regulă în 2–3 zile, inclusiv pentru firme nou înființate. Fără garanții materiale la mașini până la 30.000 EUR.</p>\r\n<div class=\"ap-facts\"><div><span>Avans</span><strong>15–50%</strong></div><div><span>Dobândă</span><strong>4,5–7,9% / an (EUR)</strong></div><div><span>Durată</span><strong>1–5 ani</strong></div><div><span>Aprobare</span><strong>în 2–3 zile</strong></div></div>\r\n<p class=\"ap-actions\"><a class=\"ap-btn\" href=\"https://autolandromania.ro/cerere_oferta.php\">Cere o ofertă de leasing</a></p>\r\n<h2>Pentru cine este</h2>\r\n<p><strong>Pentru firme de orice formă.</strong> SRL, SA, PFA, II, IF, cabinete medicale și de avocatură, producători agricoli individuali. Persoanele fizice merg pe <a href=\"https://autolandromania.ro/finantare/credit-auto/\">rate</a>.</p>\r\n<div class=\"ap-table\"><table>\r\n<tr><th>Situația firmei</th><th>Condiții</th></tr>\r\n<tr><td>Firmă nou înființată (chiar de o zi)</td><td>Avans de la 0% la anumite profiluri; fără garanții materiale pentru mașini până la 30.000 EUR; condițiile exacte pe produs <mark>[de confirmat]</mark></td></tr>\r\n<tr><td>Firmă cu vechime peste 1 an, mașină până la 30.000 EUR</td><td>Fără garanții materiale; aprobare simplificată</td></tr>\r\n<tr><td>Firmă cu vechime peste 1 an, mașină peste 30.000 EUR</td><td>Se cer garanții materiale (proprietăți, echipamente)</td></tr>\r\n<tr><td>Criterii generale</td><td>Cifră de afaceri minimum egală cu valoarea mașinii; fără datorii mari (maximum 2% din cifra de afaceri)</td></tr>\r\n</table></div>\r\n<h2>Condiții financiare</h2>\r\n<p><strong>Avans 15–50%, dobândă 4,5–7,9% pe an în EUR, comision 2,5% o singură dată, durată 1–5 ani.</strong> Dobânda se aplică doar la suma finanțată.</p>\r\n<div class=\"ap-table\"><table>\r\n<tr><th>Element</th><th>Valoare</th></tr>\r\n<tr><td>Valoare minimă</td><td>5.000 EUR + TVA</td></tr>\r\n<tr><td>Avans</td><td>15–50%</td></tr>\r\n<tr><td>Dobândă</td><td>4,5–7,9% pe an (EUR)</td></tr>\r\n<tr><td>Comision (analiză, acordare, administrare)</td><td>2,5%, o singură dată</td></tr>\r\n<tr><td>Durată</td><td>1–5 ani</td></tr>\r\n<tr><td>Valoare reziduală</td><td>1% sau 20%</td></tr>\r\n<tr><td>Rate</td><td>egale pe toată durata contractului</td></tr>\r\n</table></div>\r\n<h2>Ce mașini poți finanța</h2>\r\n<p><strong>Vechimea mașinii plus durata contractului: maximum 10 ani.</strong> Include autoutilitare. Mașină din 2019 (7 ani în 2026): maximum 3 ani de leasing. Mașină nouă: maximum 5 ani.</p>\r\n<h2>Ce câștigi fiscal</h2>\r\n<p><strong>Recuperezi TVA-ul integral, dacă ești plătitor de TVA.</strong> Cheltuielile sunt deductibile. Exemplu: 20.000 EUR + 21% TVA = 24.200 EUR, din care recuperezi 4.200 EUR. Verifică cu contabilul tău situația firmei.</p>\r\n<h2>Valoarea reziduală, pe scurt</h2>\r\n<p><strong>Suma plătită la final pentru a deveni proprietar.</strong> De obicei 1% sau 20% din valoarea mașinii. Exemplu: mașină de 20.000 EUR, valoare reziduală 1% = 200 EUR.</p>\r\n<h2>Cum se desfășoară</h2>\r\n<ol class=\"ap-steps\">\r\n <li><strong>Pasul 1:</strong> Alegi mașina și ceri oferta de leasing.</li>\r\n <li><strong>Pasul 2:</strong> Trimiți actele firmei (<a href=\"https://autolandromania.ro/finantare/acte-necesare/\">listă</a>); aprobare în 2–3 zile.</li>\r\n <li><strong>Pasul 3:</strong> Semnezi contractul, plătești avansul și comisionul, iar noi ne ocupăm de înmatriculare. Asigurarea RCA/CASCO și asistența pot fi incluse.</li>\r\n</ol>\r\n<div id=\"faq\" class=\"ap-faq\"><h2>Întrebări frecvente</h2><h3>Ce mașini pot cumpăra în leasing?</h3><p>Autovehicule și autoutilitare. Vechimea mașinii plus durata contractului nu trebuie să depășească 10 ani.</p><h3>Ce condiții trebuie să îndeplinesc?</h3><p>Cifră de afaceri minimum egală cu valoarea mașinii, fără datorii mari și avans între 15% și 50%. Firmele noi sunt acceptate.</p><h3>Pot închide contractul mai devreme?</h3><p>Da, de regulă după minimum 12 luni. Dobânda se recalculează pentru perioada folosită.</p><h3>Pot ceda contractul?</h3><p>Da, cu acordul finanțatorului. Noua persoană depune documentele necesare și preia ratele rămase.</p></div>\r\n<p class=\"ap-related\"><span>Vezi și:</span> <a href=\"https://autolandromania.ro/finantare/leasing-operational/\">Leasing operațional</a> <a href=\"https://autolandromania.ro/finantare/calculator-rate/\">Calculator rată</a> <a href=\"https://autolandromania.ro/finantare/acte-necesare/\">Acte necesare</a></p>\r\n</div>','published',2,'2026-10-21 18:32:12'),(3,'finantare','leasing-operational','Leasing operațional','Leasing operațional auto: rate deductibile, fără mașina în bilanț','Leasing operațional auto pentru firme | Autoland România','Leasing operațional auto: rate 100% deductibile, fără mașina în bilanț. Vezi pentru cine e potrivit, ce condiții se aplică și ce acte trebuie.','<div class=\"ap\">\r\n<p class=\"ap-lead\"><strong>Rate deductibile 100%, iar mașina nu apare în bilanț.</strong> Potrivit firmelor care vor indicatori financiari mai buni și flexibilitate. Nu se adresează persoanelor fizice.</p>\r\n<div class=\"ap-facts\"><div><span>Rate</span><strong>deductibile 100%</strong></div><div><span>În bilanț</span><strong>nu apare</strong></div><div><span>Durată</span><strong>1–5 ani</strong></div><div><span>Valoare minimă</span><strong>5.000 EUR + TVA</strong></div></div>\r\n<p class=\"ap-actions\"><a class=\"ap-btn\" href=\"https://autolandromania.ro/cerere_oferta.php\">Cere o ofertă de leasing operațional</a></p>\r\n<h2>Leasing operațional sau financiar?</h2>\r\n<p><strong>Operațional pentru rate deductibile și bilanț curat; financiar pentru TVA și proprietate.</strong></p>\r\n<div class=\"ap-table\"><table>\r\n<tr><th></th><th>Leasing operațional</th><th><a href=\"https://autolandromania.ro/finantare/leasing-financiar/\">Leasing financiar</a></th></tr>\r\n<tr><td>Ratele</td><td>cheltuială 100% deductibilă</td><td>cheltuieli deductibile</td></tr>\r\n<tr><td>TVA</td><td><mark>[de confirmat]</mark></td><td>deductibil integral</td></tr>\r\n<tr><td>În bilanț</td><td>nu apare</td><td>apare</td></tr>\r\n<tr><td>La final</td><td><mark>[de confirmat: returnare, prelungire sau răscumpărare]</mark></td><td>păstrezi mașina, prin valoarea reziduală</td></tr>\r\n<tr><td>Durată</td><td>1–5 ani</td><td>1–5 ani</td></tr>\r\n<tr><td>Pentru cine</td><td>firme</td><td>firme</td></tr>\r\n</table></div>\r\n<h2>Condiții</h2>\r\n<p><strong>Se aplică aceleași criterii ca la leasingul financiar: vechimea mașinii plus durata maximum 10 ani, valoare minimă 5.000 EUR + TVA, comision 2,5% o singură dată.</strong> Detaliile pe tipuri de firme sunt pe pagina <a href=\"https://autolandromania.ro/finantare/leasing-financiar/\">Leasing financiar</a>. Avansul și dobânda: <mark>[de confirmat dacă sunt aceleași]</mark>.</p>\r\n<h2>Cum se desfășoară</h2>\r\n<ol class=\"ap-steps\">\r\n <li><strong>Pasul 1:</strong> Alegi mașina și ceri oferta.</li>\r\n <li><strong>Pasul 2:</strong> Trimiți actele firmei (<a href=\"https://autolandromania.ro/finantare/acte-necesare/\">listă</a>).</li>\r\n <li><strong>Pasul 3:</strong> Semnezi contractul și preiei mașina.</li>\r\n</ol>\r\n<div id=\"faq\" class=\"ap-faq\"><h2>Întrebări frecvente</h2><h3>Cine poate lua leasing operațional?</h3><p>Firmele: SRL, PFA, II, IF, cabinete și producători agricoli individuali.</p><h3>Ratele sunt deductibile?</h3><p>Da, 100% cheltuială deductibilă. Confirmă tratamentul fiscal cu contabilul firmei.</p><h3>Mașina apare în bilanț?</h3><p>Nu.</p></div>\r\n<p class=\"ap-related\"><span>Vezi și:</span> <a href=\"https://autolandromania.ro/finantare/leasing-financiar/\">Leasing financiar</a> <a href=\"https://autolandromania.ro/finantare/acte-necesare/\">Acte necesare</a></p>\r\n</div>','published',3,'2026-10-21 18:32:12'),(4,'finantare','calculator-rate','Calculator rată','Calculator rată leasing: estimează rata lunară după preț, avans și perioadă','Calculator rată leasing auto | Autoland România','Calculează rata lunară de leasing după preț, avans și perioadă. Estimare orientativă, cu dobânda și taxele din oferta Autoland.','<div class=\"ap\">\r\n<p class=\"ap-lead\"><strong>Calculatorul estimează rata lunară de leasing pornind de la prețul mașinii, avansul și perioada aleasă.</strong> Rezultatul este orientativ; oferta finală se stabilește după analiza dosarului.</p>\r\n<div class=\"ap-facts\"><div><span>Dobândă</span><strong>{DOBANDA}% pe an</strong></div><div><span>Taxă de management</span><strong>{TAXA_MANAGEMENT}%, o singură dată</strong></div><div><span>Avans</span><strong>0–50%</strong></div><div><span>Perioadă</span><strong>12–60 de luni</strong></div></div>\r\n{CALCULATOR}\r\n<h2>Cum se calculează rata</h2>\r\n<p><strong>Rata are două părți: anuitatea (suma finanțată, dobânda și perioada) și un comision de gestiune lunar de {COMISION_LUNAR}%.</strong> Pașii sunt aceiași pentru orice mașină.</p>\r\n<div class=\"ap-table\"><table><tr><th>Element</th><th>Cum se calculează</th></tr><tr><td>Preț fără TVA</td><td>prețul afișat, împărțit la 1,21 (TVA 21%)</td></tr><tr><td>Avans</td><td>prețul fără TVA, înmulțit cu procentul de avans ales</td></tr><tr><td>Sumă finanțată</td><td>prețul fără TVA minus avansul</td></tr><tr><td>Rată lunară, fără TVA</td><td>rată egală pe toată perioada, calculată pe suma finanțată cu dobânda de {DOBANDA}% pe an, plus comisionul de gestiune lunar de {COMISION_LUNAR}% din prețul fără TVA</td></tr><tr><td>Rată lunară, cu TVA</td><td>rata fără TVA, înmulțită cu 1,21</td></tr><tr><td>Total primă plată</td><td>avans + taxă de management ({TAXA_MANAGEMENT}% din prețul fără TVA) + cheltuieli de prestări servicii ({CHELTUIELI_SERVICII} EUR); cu TVA, înmulțit cu 1,21</td></tr></table></div>\r\n<h2>Exemplu de calcul</h2>\r\n{EXEMPLU_CALCUL}\r\n<h2>Despre TVA și prețul afișat</h2>\r\n<p><strong>Calculatorul consideră prețul afișat ca preț final, cu TVA 21%.</strong> Pentru mașinile vândute într-un alt regim de TVA, de exemplu TVA nedeductibil sau regim de marjă, prețul fără TVA și rata pot diferi. Cere o ofertă pentru valorile exacte.</p>\r\n<div id=\"faq\" class=\"ap-faq\"><h2>Întrebări frecvente</h2><h3>Rata din calculator este oferta finală?</h3><p>Nu. Este o estimare orientativă. Rata finală depinde de profilul clientului, de finanțator și de dobânda și comisioanele de la data contractului.</p><h3>Ce include prima plată?</h3><p>Avansul, taxa de management de {TAXA_MANAGEMENT}% și cheltuielile de prestări servicii de {CHELTUIELI_SERVICII} EUR, toate fără TVA, la care se adaugă TVA 21%.</p><h3>De ce apar rata cu TVA și fără TVA?</h3><p>Rata fără TVA este baza de calcul, iar TVA 21% se adaugă la fiecare rată. Suma plătită efectiv este rata cu TVA.</p><h3>Pot calcula rata pentru o anumită mașină?</h3><p>Da. Pe pagina fiecărei oferte, calculatorul folosește automat prețul acesteia.</p></div>\r\n<p class=\"ap-related\"><span>Vezi și:</span> <a href=\"https://autolandromania.ro/finantare/leasing-financiar/\">Leasing financiar</a> <a href=\"https://autolandromania.ro/finantare/avans-minim/\">Avans minim</a> <a href=\"https://autolandromania.ro/finantare/acte-necesare/\">Acte necesare</a></p>\r\n</div>','published',4,'2026-10-23 10:46:57'),(5,'finantare','acte-necesare','Acte necesare','Acte necesare pentru leasing și rate auto','Acte necesare leasing și rate auto | Autoland România','Ce documente îți trebuie pentru rate sau leasing auto: persoane fizice, PFA, SRL și venituri din străinătate. Lista completă, pe înțelesul tuturor.','<div class=\"ap\">\r\n<p class=\"ap-lead\"><strong>Documentele diferă după tipul de client.</strong> Persoane fizice: buletin, adeverință de venit, factură de utilități. PFA, II, IF: acte de autorizare. Firme: acte ale societății și bilanț. Dacă nu le ai pe toate, te ghidăm noi, pas cu pas.</p>\r\n<div class=\"ap-facts\"><div><span>Persoane fizice</span><strong>4 documente</strong></div><div><span>PFA / II / IF</span><strong>5 documente</strong></div><div><span>Firme</span><strong>7 documente</strong></div><div><span>Venituri din străinătate</span><strong>+3 acte</strong></div></div>\r\n<p class=\"ap-actions\"><a class=\"ap-btn\" href=\"https://autolandromania.ro/cerere_oferta.php\">Trimite actele sau cere ajutor</a></p>\r\n<h2>Persoane fizice</h2>\r\n<p><strong>Ai nevoie de patru documente.</strong> Cererea de finanțare o primești de la noi.</p>\r\n<div class=\"ap-table\"><table>\r\n<tr><th>Document</th><th>Ce este și de unde îl iei</th></tr>\r\n<tr><td>Cerere de finanțare</td><td>O primești de la Autoland și o completezi cu datele tale</td></tr>\r\n<tr><td>Copie CI</td><td>Ambele fețe, valabilă</td></tr>\r\n<tr><td>Adeverință de venit și fișă fiscală</td><td>De la angajator, pentru minimum ultimele 3 luni</td></tr>\r\n<tr><td>O factură de utilități recentă</td><td>Pe numele tău, ca dovadă a adresei de domiciliu</td></tr>\r\n</table></div>\r\n<p><strong>Venituri din străinătate, acte suplimentare:</strong></p>\r\n<ul>\r\n <li>Contract de muncă din străinătate, tradus (traducere autorizată).</li>\r\n <li>Extrase de cont bancar pe ultimele 6 luni, ca dovadă a încasării salariului.</li>\r\n <li>Dovadă de rezidență în țara respectivă (opțional).</li>\r\n</ul>\r\n<h2>PFA, II, IF</h2>\r\n<p><strong>Ai nevoie de buletin, autorizare și registrul de încasări și plăți.</strong></p>\r\n<div class=\"ap-table\"><table>\r\n<tr><th>Document</th><th>Ce este</th></tr>\r\n<tr><td>Cerere de finanțare și formular tip</td><td>Îl primești de la Autoland</td></tr>\r\n<tr><td>Copie CI solicitant</td><td>Cartea ta de identitate</td></tr>\r\n<tr><td>Copie autorizare activitate</td><td>Certificatul de înregistrare PFA / II / IF</td></tr>\r\n<tr><td>Copie registru de încasări și plăți (anul curent)</td><td>De la contabil sau ținut de tine</td></tr>\r\n<tr><td>Dovadă venituri suplimentare (opțional)</td><td>Adeverință de venit, dacă ai și alt loc de muncă</td></tr>\r\n</table></div>\r\n<h2>Firme (SRL, SA)</h2>\r\n<p><strong>Ai nevoie de actele societății, ultimul bilanț și balanța de verificare recentă.</strong></p>\r\n<div class=\"ap-table\"><table>\r\n<tr><th>Document</th><th>Ce este</th></tr>\r\n<tr><td>Cerere de finanțare și formular tip</td><td>Îl primești de la Autoland și îl completezi cu datele firmei</td></tr>\r\n<tr><td>Copie CUI</td><td>Dovada că firma există legal</td></tr>\r\n<tr><td>Copie CI administrator / asociați</td><td>Cartea de identitate a persoanelor care conduc firma</td></tr>\r\n<tr><td>Decizie AGA</td><td>Doar dacă sunt minimum 2 asociați</td></tr>\r\n<tr><td>Copie act constitutiv (ultima versiune)</td><td>Documentul de înființare, sau cel mai recent act dacă au fost modificări (administrator nou, schimbare de asociați)</td></tr>\r\n<tr><td>Ultimul bilanț, cu recipisa ANAF și balanța aferentă</td><td>Situația financiară pe ultimul an încheiat, de la contabilitate</td></tr>\r\n<tr><td>Balanța de verificare recentă</td><td>Pentru anul în curs, din luna precedentă</td></tr>\r\n</table></div>\r\n<p>Firmele noi: bilanțul lipsește, iar lista exactă se stabilește la cerere <mark>[de confirmat]</mark>.</p>\r\n<h2>Cum depui actele</h2>\r\n<ol class=\"ap-steps\">\r\n <li><strong>Pasul 1:</strong> Alegi categoria ta și strângi documentele din listă.</li>\r\n <li><strong>Pasul 2:</strong> Ni le trimiți <mark>[canal: e-mail / formular / WhatsApp – de confirmat]</mark>.</li>\r\n <li><strong>Pasul 3:</strong> Verificăm dosarul și îți spunem dacă lipsește ceva; leasingul se aprobă de regulă în 2–3 zile.</li>\r\n</ol>\r\n<div id=\"faq\" class=\"ap-faq\"><h2>Întrebări frecvente</h2><h3>Ce fac dacă nu am toate actele?</h3><p>Contactează-ne. Îți spunem ce lipsește, de unde îl obții și cum îl completezi.</p><h3>Ce înseamnă fișă fiscală?</h3><p>Documentul de la angajator care arată veniturile și impozitele plătite.</p><h3>Sunt acceptate actele din străinătate?</h3><p>Da, cu traducere autorizată pentru contractul de muncă și extrase de cont pe 6 luni.</p></div>\r\n<p class=\"ap-related\"><span>Vezi și:</span> <a href=\"https://autolandromania.ro/finantare/credit-auto/\">Credit auto</a> <a href=\"https://autolandromania.ro/finantare/leasing-financiar/\">Leasing financiar</a> <a href=\"https://autolandromania.ro/finantare/avans-minim/\">Avans minim</a></p>\r\n</div>','published',5,'2026-10-21 18:32:12'),(6,'finantare','avans-minim','Avans minim','Avans minim la rate și leasing: cât ai nevoie, de fapt','Avans minim la rate și leasing auto | Autoland România','Avans de la 0% la rate, 15–50% la leasing, de la 20% pentru venituri din străinătate. Vezi cine primește avans 0% și ce condiții se aplică.','<div class=\"ap\">\r\n<p class=\"ap-lead\"><strong>Avans de la 0% la rate; 15–50% la leasing.</strong> Cu venituri din străinătate, de la 20%. Avansul 0% nu se aplică oricui: depinde de profilul tău și de dosar. Mai jos vezi condițiile pe fiecare situație.</p>\r\n<div class=\"ap-facts\"><div><span>Rate</span><strong>de la 0%</strong></div><div><span>Leasing</span><strong>15–50%</strong></div><div><span>Venituri din străinătate</span><strong>de la 20%</strong></div><div><span>Istoric dificil</span><strong>15–30%</strong></div></div>\r\n<p class=\"ap-actions\"><a class=\"ap-btn\" href=\"https://autolandromania.ro/cerere_oferta.php\">Aflu ce avans mi se aplică</a></p>\r\n<h2>Avans pe tip de client</h2>\r\n<p><strong>Cu cât istoricul și veniturile sunt mai bune, cu atât avansul poate fi mai mic.</strong></p>\r\n<div class=\"ap-table\"><table>\r\n<tr><th>Situație</th><th>Avans</th><th>Condiții</th></tr>\r\n<tr><td>Persoană fizică, venituri din România (rate)</td><td>de la 0%</td><td>Venit minim 2.000 RON/lună, minimum 3 luni vechime; în funcție de istoric bancar</td></tr>\r\n<tr><td>Persoană fizică, venituri din străinătate (rate)</td><td>de la 20%</td><td>Venituri dovedite minimum 6 luni, fără garanții materiale</td></tr>\r\n<tr><td>Istoric bancar dificil (rate)</td><td>15–30%</td><td>Acceptat; dosar analizat individual</td></tr>\r\n<tr><td>Firmă nou înființată</td><td>de la 0% la anumite profiluri</td><td>Fără garanții materiale pentru mașini până la 30.000 EUR <mark>[de confirmat avansul exact]</mark></td></tr>\r\n<tr><td>Firmă peste 1 an, mașină până la 30.000 EUR</td><td>de la 0% la anumite profiluri</td><td>Fără garanții materiale</td></tr>\r\n<tr><td>Firmă peste 1 an, mașină peste 30.000 EUR</td><td>de la 0% la anumite profiluri</td><td>Cu garanții materiale</td></tr>\r\n<tr><td>Leasing (financiar sau operațional)</td><td>15–50%</td><td>Tu alegi în interval: avans mic = rate mai mari</td></tr>\r\n</table></div>\r\n<h2>Ce înseamnă avansul pentru rata ta</h2>\r\n<p><strong>Avans mic înseamnă rate mai mari; avans mare înseamnă rate mai mici.</strong> Dobânda se aplică doar la suma finanțată, nu la avans. Exemplu: mașină de 15.000 EUR, avans 5.000 EUR → dobânda se calculează la 10.000 EUR.</p>\r\n<p>Exemple cu cifre: <a href=\"https://autolandromania.ro/finantare/calculator-rate/\">Calculator rată</a>.</p>\r\n<h2>Exemplu cu venituri din străinătate</h2>\r\n<p><strong>Exemplu: 8 luni de muncă în Germania, mașină de 12.000 EUR.</strong> Avans 20% = 2.400 EUR, finanțezi 9.600 EUR. Rata exactă depinde de durata și dobânda stabilite la ofertă.</p>\r\n<h2>Cum aflii avansul care ți se aplică</h2>\r\n<ol class=\"ap-steps\">\r\n <li><strong>Pasul 1:</strong> Alegi mașina și ne spui ce venituri ai (România sau străinătate) și dacă ai restanțe.</li>\r\n <li><strong>Pasul 2:</strong> Îți spunem avansul orientativ și actele necesare (<a href=\"https://autolandromania.ro/finantare/acte-necesare/\">listă</a>).</li>\r\n <li><strong>Pasul 3:</strong> După analiza dosarului primești oferta finală.</li>\r\n</ol>\r\n<div id=\"faq\" class=\"ap-faq\"><h2>Întrebări frecvente</h2><h3>Pot cumpăra mașina fără avans?</h3><p>La rate, uneori da, în funcție de venituri și istoric bancar. La leasing, avansul este între 15% și 50%.</p><h3>Ce avans am cu istoric negativ în Biroul de Credit?</h3><p>De obicei între 15% și 30%, după analiza dosarului. Nu putem promite aprobarea.</p><h3>Plătesc dobândă la avans?</h3><p>Nu. Dobânda se calculează doar la suma finanțată.</p><h3>Un avans mai mare scade rata?</h3><p>Da. Avansul mai mare reduce suma finanțată, deci și rata.</p></div>\r\n<p class=\"ap-related\"><span>Vezi și:</span> <a href=\"https://autolandromania.ro/finantare/credit-auto/\">Credit auto</a> <a href=\"https://autolandromania.ro/finantare/leasing-financiar/\">Leasing financiar</a> <a href=\"https://autolandromania.ro/finantare/acte-necesare/\">Acte necesare</a></p>\r\n</div>','published',6,'2026-10-21 18:32:12'),(7,'pagini','despre-noi','Despre noi','Despre Autoland România: parc auto din Iași, din 2007','Despre noi: parc auto second hand din Iași | Autoland','Autoland România, parc auto din Iași, din 2007: cum alegem și verificăm mașinile, ce servicii oferim, date despre firmă, program și contact.','<div class=\"ap\">\r\n<p class=\"ap-lead\"><strong>Autoland România este un parc auto second hand din Iași, pe strada Luca Arbore nr. 3, activ din 2007.</strong> Vindem autoturisme, autoutilitare, autospecializate și utilaje, aduse din import european și verificate într-un service autorizat înainte de vânzare. Clienții noștri sunt persoane fizice și firme din toată țara.</p>\r\n<div class=\"ap-facts\"><div><span>Activ din</span><strong>2007</strong></div><div><span>Oferte auto</span><strong>peste {NR_MASINI}</strong></div><div><span>Mașini vândute</span><strong><mark>[de completat]</mark></strong></div><div><span>Recenzii Google</span><strong><mark>[număr și notă]</mark></strong></div></div>\r\n<p class=\"ap-actions\"><a class=\"ap-btn\" href=\"https://autolandromania.ro/vanzari.php\">Vezi ofertele auto</a> <a class=\"ap-btn ap-btn-ghost\" href=\"https://autolandromania.ro/contact.php\">Contact</a></p>\r\n<h2>Cine suntem</h2>\r\n<p><strong>Autoland România vinde mașini din 2007, de la Iași, și se ocupă de tot ce urmează după alegerea mașinii: finanțare, acte, înmatriculare și livrare.</strong> Lucrăm cu mașini second hand și noi din import, de la autoturisme și autoutilitare sub 3,5 t până la autospecializate și utilaje de construcții sau agricole. Parcul nostru se află în incinta KIA Iași / Trado Motors.</p>\r\n<div class=\"ap-cols\">\r\n<div><h3>Vindem</h3><p>Autoturisme, autoutilitare, autospecializate și utilaje, din ofertele noastre sau <a href=\"https://autolandromania.ro/cerere_oferta.php\">la comandă</a>, cu marca, motorizarea și dotările alese de client.</p></div>\r\n<div><h3>Finanțăm</h3><p>Rate sau leasing pe 1–5 ani, pentru persoane fizice și firme, inclusiv firme noi și clienți cu venituri din străinătate. <a href=\"https://autolandromania.ro/leasing.php\">Condiții și acte</a></p></div>\r\n<div><h3>Rezolvăm actele</h3><p>Înmatriculare, numere valabile, asigurare, omologare RAR la cerere și livrare la adresa clientului, în toată România.</p></div>\r\n</div>\r\n<h2>Ce servicii oferim</h2>\r\n<p><strong>Clientul primește mașina cu tot ce ține de ea rezolvat într-un singur loc, de la oferta personalizată la predarea cheilor.</strong> Fiecare serviciu are condițiile scrise înainte de semnarea contractului.</p>\r\n<div class=\"ap-table\"><table>\r\n<tr><th>Serviciu</th><th>Ce include</th></tr>\r\n<tr><td>Consultanță și oferte personalizate</td><td>Discutăm nevoile clientului și stabilim împreună mașina potrivită și varianta de plată: cash, rate sau leasing</td></tr>\r\n<tr><td>Mașini la comandă</td><td>Aducem din import european mașina cerută, cu configurația dorită, la un preț stabilit din start</td></tr>\r\n<tr><td>Verificare tehnică</td><td>Service autorizat, verificare la fața locului, drive-test și raport Car Vertical <mark>[de confirmat]</mark></td></tr>\r\n<tr><td><a href=\"https://autolandromania.ro/garantie.php\">Garanție</a></td><td>12–36 de luni, în contract separat de contractul de vânzare</td></tr>\r\n<tr><td><a href=\"https://autolandromania.ro/leasing.php\">Finanțare</a></td><td>Rate sau leasing financiar ori operațional, pe 1–5 ani, pentru persoane fizice și firme</td></tr>\r\n<tr><td><a href=\"https://autolandromania.ro/inmatriculari.php\">Înmatriculări și acte</a></td><td>Înmatriculare, numere valabile, asigurare RCA/CASCO, omologare RAR la cerere, inclusiv pentru mașini cumpărate în altă parte</td></tr>\r\n<tr><td>Servicii pentru firme</td><td>Modificări de caroserie, echipare frigorifică, autorizări ISCIR pentru autoutilitare și autospecializate</td></tr>\r\n<tr><td>Livrare</td><td>Transport autorizat pe platformă, cu asigurarea mașinii, la parc sau la adresa clientului, în toată România</td></tr>\r\n<tr><td><a href=\"https://autolandromania.ro/asistenta-rutiera.php\">Asistență rutieră</a></td><td>Pachete pentru România sau UE, la cerere</td></tr>\r\n</table></div>\r\n<h2>Cum alegem și verificăm mașinile</h2>\r\n<p><strong>Fiecare mașină trece prin aceiași pași, de la identificare până la livrare, iar clientul primește documentele fiecărui pas.</strong> Mașinile vin din Germania, Austria, Belgia, Olanda și Franța, din oferte certificate ale unor platforme profesionale. <mark>[de confirmat: sursele principale]</mark></p>\r\n<ol class=\"ap-steps\">\r\n<li><strong>Pasul 1: Identificăm mașina.</strong> Căutăm după criteriile clientului: marcă, an, motorizare, dotări, buget.</li>\r\n<li><strong>Pasul 2: O verificăm la fața locului.</strong> Verificăm mașina real, nu doar anunțul, și istoricul ei, inclusiv kilometrajul.</li>\r\n<li><strong>Pasul 3: Verificare într-un service autorizat.</strong> Controlul tehnic se face înainte de cumpărare și înainte de livrare.</li>\r\n<li><strong>Pasul 4: Pregătim livrarea.</strong> Transport pe platformă, cu asigurare, apoi detailing și numere valabile.</li>\r\n<li><strong>Pasul 5: Predăm mașina cu documentele ei.</strong> Istoric de service, manuale, facturi, asigurare și contractul de garanție.</li>\r\n</ol>\r\n<h2>Ce promitem și unde găsești scris</h2>\r\n<p><strong>Ce îți spunem la discuție se regăsește în documentele pe care le semnezi.</strong> Nu promitem ce nu depinde de noi: aprobarea finanțării este decizia băncii sau a societății de leasing.</p>\r\n<div class=\"ap-table\"><table>\r\n<tr><th>Angajament</th><th>Unde îl găsești</th></tr>\r\n<tr><td>Prețul mașinii, fără taxe ascunse</td><td>Oferta scrisă și contractul de vânzare</td></tr>\r\n<tr><td>Garanția de 12–36 de luni</td><td><a href=\"https://autolandromania.ro/garantie.php\">Contractul de garanție</a>, separat de contractul de vânzare</td></tr>\r\n<tr><td>Termenul de livrare la mașinile la comandă</td><td>Contractul de comandă <mark>[de confirmat]</mark></td></tr>\r\n<tr><td>Costul finanțării și al comisionului</td><td><a href=\"https://autolandromania.ro/finantare/calculator-rate/\">Calculatorul de rată</a> și oferta finanțatorului, înainte de semnare</td></tr>\r\n<tr><td>Istoricul și documentele mașinii</td><td>Dosarul predat la livrare</td></tr>\r\n</table></div>\r\n<h2>Unde ne găsiți</h2>\r\n<div class=\"ap-where\"><div><div class=\"ap-table\"><table><tr><td>Adresă</td><td>Strada Luca Arbore nr. 3, Iași 700440, România (în incinta KIA Iași / Trado Motors)</td></tr><tr><td>Program</td><td>luni–vineri, 10:00–18:00</td></tr><tr><td>Telefon</td><td><a href=\"tel:+40742377001\">0742 377 001</a></td></tr><tr><td>E-mail</td><td><a href=\"mailto:office@autolandromania.ro\">office@autolandromania.ro</a></td></tr><tr><td>Hartă</td><td><a href=\"https://maps.app.goo.gl/cuxVc4u2BkxwVWXt6\">Deschide în Google Maps</a></td></tr></table></div></div>{HARTA}</div>\r\n<h2>Date despre firmă</h2>\r\n<div class=\"ap-table\"><table><tr><td>Denumire</td><td>S.C. Autoland S.R.L.</td></tr><tr><td>CUI</td><td>RO 21834696</td></tr><tr><td>Nr. de înregistrare la Registrul Comerțului</td><td>J22/1605/2007</td></tr><tr><td>Operator de date cu caracter personal</td><td>nr. 15357</td></tr></table></div>\r\n<p class=\"ap-related\"><span>Vezi și:</span> <a href=\"https://autolandromania.ro/garantie.php\">Garanție</a> <a href=\"https://autolandromania.ro/leasing.php\">Leasing și rate</a> <a href=\"https://autolandromania.ro/impresii.php\">Păreri clienți</a> <a href=\"https://autolandromania.ro/contact.php\">Contact</a></p>\r\n</div>','published',1,'2026-10-23 10:46:57');
