--
-- Table structure for table `texte`
--

DROP TABLE IF EXISTS `texte`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `texte` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `home` longtext DEFAULT NULL,
  `tandc` longtext DEFAULT NULL,
  `leasing` longtext DEFAULT NULL,
  `servicii` longtext DEFAULT NULL,
  `rent` longtext DEFAULT NULL,
  `cond_rent` longtext DEFAULT NULL,
  `contact` longtext DEFAULT NULL,
  `inmatriculari` longtext DEFAULT NULL,
  `asistenta_rutiera` longtext DEFAULT NULL,
  `garantie` longtext DEFAULT NULL,
  `email_recenzii` longtext DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
